'use strict';

// MAIN //

/**
* Returns an editor configuration for padding properties.
*
* @returns {Object} configuration
*
* @example
* var o = config();
* // returns {...}
*/
function config() {
	return {
		'bottom': {
			'description': 'bottom padding',
			'property': 'bottom',
			'default': 0,
			'type': 'number',
			'step': 1,
			'units': 'px'
		},
		'left': {
			'description': 'left padding',
			'property': 'left',
			'default': 0,
			'type': 'number',
			'step': 1,
			'units': 'px'
		},
		'right': {
			'description': 'right padding',
			'property': 'right',
			'default': 0,
			'type': 'number',
			'step': 1,
			'units': 'px'
		},
		'top': {
			'description': 'top padding',
			'property': 'top',
			'default': 0,
			'type': 'number',
			'step': 1,
			'units': 'px'
		}
	};
}


// EXPORTS //

module.exports = config;
